    // every bay
    pkLotBays().forEach(function (b) { box(1.7, 0.12, 0.22, MAT.steelDark, b.x, 0.06, b.front + (b.front < 62 ? 0.5 : -0.5)); });
    // lamp posts down the edges of the lot
