    toast(S.coasterKey ? 'The coaster: operator key ON - unlocked' : 'The coaster: operator key OFF - locked', S.coasterKey ? 'good' : '');
    logEvent(S.coasterKey ? 'The coaster unlocked' : 'The coaster locked', '');
