    if (rows % 2 === 0) rows++;
    var R = Math.ceil(N / rows);
    var sz = (a.plot && a.plot.qside) || 1;
    a.laneGeo = { N: R * rows, R: R, rows: rows, dir: a.qdx >= 0 ? 1 : -1, sz: sz, step: 1.05, pitch: 1.1, z0: a.qz - sz * 1.1 * (rows - 1) / 2 };
    return a.laneGeo;
