      for (i = 0; i < 40; i++) sphere(0.05, fly, X0 + 1 + rng() * (X1 - X0 - 2), 11.6 + rng() * 1.6, Z0 + 1 + rng() * (Z1 - Z0 - 6), g);
      var leaf = [0x2f4a2a, 0x3a5a33, 0x2a4226];
