    for (var k = 0; k < 4; k++) box(0.08, 0.1, 0.006, pkBkStd({ color: [0xf2efe6, 0xe8d79a, 0xf2efe6, 0xc9e0f0][k], roughness: 0.8 }), 0.22, 0.09 - k * 0.065, 0.06, g);
