    var sc = touchScreen({ w: 240, h: 168, pw: 0.44, ph: 0.3, x: 0, y: 0.01, z: 0.0, parent: g, title: title, draw: draw });
    PK_BK_LIVE.push({ sc: sc, g: g, every: 0.5 });
