        R.txt('LAMP TEST', 0.12, -0.175, 0.013, '#aebcc4'); R.txt('HORN', 0.285, -0.175, 0.013, '#aebcc4');
        R.box(0.2, -0.33, 0.36, 0.12, 'rgba(0,0,0,0.22)', 0.004);
