      player.x = PK_SIT.x; player.z = PK_SIT.z; player.y = PK_SIT.y; player.vy = 0;
      camera.position.set(PK_SIT.x, PK_SIT.y + 1.42, PK_SIT.z);   // a seated eye on the bigger chair, over the desk
