    pkBevelBox(W - 0.3, 0.8, 0.03, timber, 0, F + 0.46, bz0 + 0.085, g, 0.01);
    pkBevelBox(W - 0.28, 0.04, 0.05, MAT.trim, 0, F + 0.88, bz0 + 0.09, g, 0.008);
