      var gu = pkSpawnGuest(), off = side[i];
      // the bay runs along z: the doors are either side in x
      gu.rec.x = b.x + off[0] * 1.15; gu.rec.z = b.z + off[1]; gu.g.position.set(gu.rec.x, 0, gu.rec.z);
      gu.car = car; car.party.push(gu);
