      if (car.state === 'in') { car.s = car.path.len; car.v = 0; pkLotPlace(car); pkLotUnload(car); }
      else if (car.state === 'back') { car.state = 'out'; car.rev = false; car.path = pkLotPath(car.out.fwd); car.s = 0; car.bay.car = null; }
