      var cast = X.cast; if (cast) Object.keys(cast).forEach(function (k) { var A = cast[k]; if (!A.on) return; var p = P(A.x, A.z); c.fillStyle = A.col || '#fff'; c.beginPath(); c.arc(p[0], p[1], 5, 0, 6.283); c.fill(); });
