    var back = new THREE.Mesh(new THREE.CircleGeometry(0.34, 22), std({ color: 0xf4efe0, roughness: 0.5 })); back.position.set(x, y + 2.62, z - 0.03); back.rotation.y = Math.PI; back.userData.noBake = true; g.add(back);
