    for (var tb = -31; tb <= 31; tb += 0.6) box(0.18, 0.02, 0.18, pkPaint(0xf0c63a, 0.6, 0.1), tb, 0.99, 2.72, g);
    
    // FIXED: The ramp properly slopes away from the platform down to the ground
