    var l2 = 'STEAM ' + Math.round(t.press * 100) + '%   COAL ' + Math.round(R.fuel) + '%   WATER ' + Math.round(R.water) + '%   WEAR ' + Math.round(R.wear) + '%   DIRT ' + Math.round(R.dirt) + '%';
